    do { (void)(cond); (void)(msg); } while (0)
#  define VK_ENSURES(cond, msg) \
    do { (void)(cond); (void)(msg); } while (0)
#else
#  define VK_EXPECTS(cond, msg)                                              \
    do {                                                                     \
      if (!(cond)) throw ::std::invalid_argument(std::string(msg) + ": " + #cond); \
