  float dummy[4]={0,0,0,0}; int32_t didx[2]={0,0};
  printf("[divisibility] topk=2, block_I=4, inner_iter=1 (expect INVALID_ARGUMENT, no hang)\n");
  g_fail += run_invalid("divisibility", 1,1,2,4,1, dummy,dummy,didx,dummy,nullptr,0, "multiple of");

  // Invalid alias: topk=2, block_I=2, inner_iter=1 (2%2==0 valid div), but out==q.
  printf("[alias] out == q (expect INVALID_ARGUMENT, no hang)\n");
  g_fail += run_invalid("alias", 1,1,2,2,1, dummy,dummy,didx,dummy,nullptr,0, "alias");

  // Invalid alias with lse: out == lse when return_lse.
  float lse[2]={0,0};
  printf("[alias-lse] out == lse, return_lse=1 (expect INVALID_ARGUMENT, no hang)\n");
  g_fail += run_invalid("alias-lse", 1,1,2,2,1, dummy,dummy,didx,lse,lse,1, "alias");

  printf("=== RESULT: %s (failures=%d) ===\n", g_fail?"FAILED":"ALL PASS", g_fail);
  return g_fail ? 1 : 0;
}
